    h, w = len(grid), len(grid[0])
    # Uniform separator rows/columns define the panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != 0]
    frame = grid[sep_rows[0]][0]
    row_starts = [0] + [r + 1 for r in sep_rows]
    row_ends = sep_rows + [h]
    col_starts = [0] + [c + 1 for c in sep_cols]
    col_ends = sep_cols + [w]
    nr, nc = len(row_starts), len(col_starts)
    # Find the panel containing the non-square stencil.
    stencil = None
    for i, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        for j, (c0, c1) in enumerate(zip(col_starts, col_ends)):
            cells = {(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, frame)}
            if cells and (len(cells) != 4 or len({r for r, _ in cells}) != 2 or len({c for _, c in cells}) != 2):
                stencil = cells
                break
        if stencil is not None:
            break
    if stencil is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(zip(row_starts, row_ends)):
        # The marker color in the first panel identifies this band's output color.
        marker = next((grid[r][c] for r in range(r0, r1) for c in range(col_starts[0], col_ends[0])
